const parsed = JSON.parse('{"books":[{"isbn":"111","title":"A"},{"isbn":"222","title":"B"}]}');

// Untyped: works, but `b` is `any` - a typo inside would not be caught.
const loose = parsed.books.map((b) => b.isbn);

// Typed: the shape is stated, so `b.isbnn` would fail to compile.
const tight = parsed.books.map((b: { isbn: string }) => b.isbn);

console.log("loose:", loose);
console.log("tight:", tight);
console.log("same result, different safety");

// Simulated, to show the failure shape without a network call.
async function fakeResponse() {
  return { json: async () => ({ books: [{ title: "Git Pocket Guide" }] }) };
}

const response = await fakeResponse();

const forgotten = response.json();            // no await
console.log("without await:", forgotten.constructor.name, "<- a Promise, not your data");
console.log("  .books is  :", (forgotten as { books?: unknown }).books);

const correct = await response.json();        // with await
console.log("with await   :", correct.books[0].title);

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

// Backslashes before ` and ${ because each file sits inside a template literal.

await writeProjectFile("week7/generated/day3-first-api.spec.ts", `// Week 7, Day 3 — your first API tests.
//
// Not one \`page\` in this file, and no browser is launched. The whole game is
// request in, response out.
//
// Written by a cell in week7/day3_2.ipynb. Run it yourself:
//   npx playwright test week7/generated/day3-first-api.spec.ts
import { test, expect } from "@playwright/test";

const BASE_URL = "https://demoqa.com";
const KNOWN_ISBN = "9781449325862";   // "Git Pocket Guide" — verified live

test.describe("Reading data with GET", () => {
  test("Step 1 — send a request, check the status", async ({ request }) => {
    const response = await request.get(\`\${BASE_URL}/BookStore/v1/Books\`);

    // Verification one of two: did the server accept the request?
    expect(response.status()).toBe(200);
  });

  test("Step 2 — two ways to read the body", async ({ request }) => {
    const response = await request.get(\`\${BASE_URL}/BookStore/v1/Books\`);

    // The session writes this. It works, and it is one step longer than needed.
    const viaText = JSON.parse(await response.text());

    // Playwright parses it for you. Prefer this.
    const viaJson = await request
      .get(\`\${BASE_URL}/BookStore/v1/Books\`)
      .then((r) => r.json());

    expect(viaText.books.length).toBe(viaJson.books.length);
    expect(Array.isArray(viaText.books)).toBe(true);
  });

  test("Step 3 — reaching into the body", async ({ request }) => {
    const response = await request.get(\`\${BASE_URL}/BookStore/v1/Books\`);
    const body = await response.json();

    // \`books\` is the parent, \`isbn\` the child. You cannot skip a level.
    expect(body.books.length).toBeGreaterThan(0);

    const isbns = body.books.map((b: { isbn: string }) => b.isbn);
    expect(isbns).toContain(KNOWN_ISBN);
  });

  test("Step 4 — one resource instead of the collection", async ({ request }) => {
    const response = await request.get(\`\${BASE_URL}/BookStore/v1/Book?ISBN=\${KNOWN_ISBN}\`);

    expect(response.status()).toBe(200);
    const book = await response.json();

    // Verification two of two: is the body the right body?
    expect(book.isbn).toBe(KNOWN_ISBN);
    expect(book.title).toBe("Git Pocket Guide");
    expect(book.author).toContain("Silverman");
  });

  test("Step 5 — the negative case", async ({ request }) => {
    const response = await request.get(\`\${BASE_URL}/BookStore/v1/Book?ISBN=0000000000\`);

    // 400 here, not the 404 the session predicts — see day2_2, Step 3.
    expect(response.status()).toBe(400);
    const body = await response.json();
    expect(body.message).toContain("not available");
  });
});

test.describe("Creating data with POST", () => {
  // SERIAL, deliberately. These two tests share a user, and the repo config sets
  // fullyParallel: true - so without this line they land in different workers,
  // each computing its own userName, and Step 7 asks for a token for a user that
  // was never created. It fails with \`token: null\`, which looks like an API bug
  // and is not one. Serial mode was taught in week3/day2_2.
  //
  // Sharing state between tests is what day4_2 replaces with beforeAll.
  test.describe.configure({ mode: "serial" });

  // A unique name per run: this is a shared public sandbox, and a fixed name
  // would collide with itself the second time you ran the file.
  const userName = \`w7d3_\${Date.now()}\`;
  const password = "Passw0rd@123";
  let userId = "";

  test("Step 6 — POST sends a body and gets 201", async ({ request }) => {
    const response = await request.post(\`\${BASE_URL}/Account/v1/User\`, {
      data: { userName, password },
    });

    // 201, not 200: "created". A GET could never return this.
    expect(response.status()).toBe(201);

    const body = await response.json();
    expect(body.username).toBe(userName);
    // The id was invented by the server. We could not have known it in advance -
    // which is the whole problem day4_2 solves.
    expect(body.userID).toBeTruthy();
    userId = body.userID;
  });

  test("Step 7 — a token, which you cannot predict", async ({ request }) => {
    const response = await request.post(\`\${BASE_URL}/Account/v1/GenerateToken\`, {
      data: { userName, password },
    });

    expect(response.status()).toBe(200);
    const body = await response.json();

    // toBeTruthy, not toBe("..."): the token is different every time, so the
    // only honest assertion is that there IS one.
    expect(body.token).toBeTruthy();
    expect(body.status).toBe("Success");
  });

  test.afterAll(async ({ request }) => {
    // Clean up after ourselves on a shared sandbox.
    if (!userId) return;
    const tokenResponse = await request.post(\`\${BASE_URL}/Account/v1/GenerateToken\`, {
      data: { userName, password },
    });
    const { token } = await tokenResponse.json();
    await request.delete(\`\${BASE_URL}/Account/v1/User/\${userId}\`, {
      headers: { Authorization: \`Bearer \${token}\` },
    });
  });
});
`);

// Expected: 7 passed. No browser window appears - there is no browser.
await runSpec("week7/generated/day3-first-api.spec.ts");

// Both forms against the same endpoint, plus the raw text so you can see what
// .json() is doing for you.
const res = await fetch("https://demoqa.com/BookStore/v1/Book?ISBN=9781449325862");
const raw = await res.text();

console.log("raw text (first 90):", raw.slice(0, 90));
console.log("parsed title       :", JSON.parse(raw).title);

// Proof that Playwright's `data` and a hand-written body reach the same place -
// here done with fetch so you can see the header you would otherwise forget.
const B = "https://demoqa.com";
const attempt = await fetch(`${B}/Account/v1/User`, {
  method: "POST",
  // Leave this header out and many APIs answer 415 Unsupported Media Type.
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ userName: "", password: "" }),
});
console.log("status:", attempt.status);
console.log("body  :", (await attempt.text()).slice(0, 90));

// Why a constant beats a literal, before you even reach a config file.
const environments = {
  local: "http://localhost:3000",
  staging: "https://staging.demoqa.com",
  prod: "https://demoqa.com",
};

// One value decides where every request goes.
const chosen = environments[(Deno.env.get("TEST_ENV") ?? "prod") as keyof typeof environments];
console.log("TEST_ENV     :", Deno.env.get("TEST_ENV") ?? "(unset)");
console.log("requests go  :", chosen);
console.log("endpoint     :", `${chosen}/BookStore/v1/Books`);

## One `describe` per endpoint

```
test.describe("GET /BookStore/v1/Books", () => {
  test("returns 200 and a non-empty list", ...);
  test("every book has an isbn", ...);
});

test.describe("GET /BookStore/v1/Book", () => {
  test("a known ISBN returns that book", ...);
  test("an unknown ISBN returns 400", ...);
});
```

Naming the `describe` after the **endpoint** rather than the feature means a failure report tells
you which service broke - and that is what you hand to the team that owns it.

